<script setup lang="ts">
import {ref,computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useCoffee} from '../stores/coffee';import type {Product,Order} from '../../../../packages/shared/src/types';import {money} from '../../../../packages/shared/src/domain';import ProductPhoto from '../components/ProductPhoto.vue';import ProductOptions from '../components/ProductOptions.vue';import PaymentDialog from '../components/PaymentDialog.vue';import Icon from '../components/Icon.vue';
const s=useCoffee();const route=useRoute();const router=useRouter();const query=ref('');const category=ref('all');const selected=ref<Product>();const editIndex=ref(-1);const payment=ref<Order>();const cartOpen=ref(false);const key=ref(crypto.randomUUID());
const items=computed(()=>s.state.products.filter(p=>p.active&&(category.value==='all'||p.category===category.value)&&p.name.toLocaleLowerCase('vi').includes(query.value.toLocaleLowerCase('vi'))));
const count=computed(()=>s.cart.reduce((n,l)=>n+l.quantity,0));const waiter=computed(()=>Boolean(route.meta.waiter));
function choose(p:Product,index=-1){if(!p.available){s.notify('Món này đang hết hàng.');return}selected.value=p;editIndex.value=index}
function add(line:any){if(editIndex.value>=0)s.cart.splice(editIndex.value,1,line);else s.addLine(line)}
function submit(pay=false){if(!s.cart.length)return;const order=s.submit(waiter.value?'waiter':'pos',key.value);if(order){key.value=crypto.randomUUID();if(pay)payment.value=order;cartOpen.value=false}}
</script>
<template><div class="pos-layout" :class="{waiter}"><section class="menu-pane"><div class="pos-mobile-context" v-if="waiter"><h2>Chọn bàn để phục vụ</h2><select v-model="s.tableId" aria-label="Bàn phục vụ"><option v-for="t in s.tables" :key="t.id" :value="t.id">{{t.name}} · {{t.area}}</option><option value="takeaway">Mang đi</option></select></div><div class="menu-toolbar"><label class="search-field"><Icon name="search"/><input v-model="query" placeholder="Tìm món, tên đồ uống..." aria-label="Tìm món"><kbd>/</kbd></label><button class="icon-button" aria-label="Quản lý thực đơn" @click="router.push('/admin/products')"><Icon name="settings"/></button></div><div class="category-tabs" role="group" aria-label="Danh mục món"><button :class="{selected:category==='all'}" @click="category='all'">Tất cả <small>{{s.state.products.filter(p=>p.active).length}}</small></button><button v-for="c in s.state.categories" :key="c.id" :class="{selected:category===c.id}" @click="category=c.id">{{c.name}}</button></div><div class="section-note"><span>{{items.length}} món trong thực đơn</span><span><i class="tiny-dot"></i>Giá đã niêm yết</span></div><div class="product-grid"><article v-for="p in items" :key="p.id" class="product-card" :class="{unavailable:!p.available}"><button class="product-image-button" :aria-label="'Chọn '+p.name" @click="choose(p)" :disabled="!p.available"><ProductPhoto :photo="p.photo" :image="p.image" :name="p.name"/><span class="product-tag" v-if="p.category==='combo'">Combo</span><span class="sold-out" v-if="!p.available">Hết hàng</span></button><div class="product-card-info"><div><h2>{{p.name}}</h2><p>{{money(p.price)}}</p></div><button class="add-button" :aria-label="'Thêm nhanh '+p.name" :disabled="!p.available" @click="s.addLine({productId:p.id,quantity:1,variantId:p.variants[0].id,optionIds:[],note:''})"><Icon name="plus"/></button></div></article></div><div v-if="!items.length" class="empty"><Icon name="search" :size="36"/><h3>Không tìm thấy món</h3><p>Thử tìm tên khác hoặc chọn danh mục khác.</p></div></section><aside class="bill-pane" :class="{mobileOpen:cartOpen}"><header class="bill-heading"><div><h2>Đơn hiện tại <span>{{count}}</span></h2><label class="table-select"><Icon name="table"/><select v-model="s.tableId" aria-label="Bàn của đơn"><option v-for="t in s.tables" :key="t.id" :value="t.id">{{t.name}}</option><option value="takeaway">Mang đi</option></select><Icon name="down" :size="16"/></label></div><span class="status pending">Chưa thanh toán</span><button class="icon-button close-cart" aria-label="Đóng giỏ hàng" @click="cartOpen=false"><Icon name="close"/></button></header><div class="bill-lines"><div v-if="!s.cart.length" class="empty"><Icon name="cart" :size="42"/><h3>Chọn món để bắt đầu</h3><p>Thêm đồ uống từ thực đơn bên cạnh.</p></div><article v-for="(line,i) in s.priced" :key="i" class="bill-line"><ProductPhoto :photo="line.photo" :image="line.image" :name="line.name"/><div class="bill-line-main"><button class="line-name" @click="choose(s.state.products.find(p=>p.id===line.productId)!,i)">{{line.name}}</button><small>{{money(line.unitPrice)}}<span v-if="line.variantId!=='m'"> · Size {{line.variant}}</span></small><small v-if="line.optionNames.length">{{line.optionNames.join(', ')}}</small><small v-if="line.note" class="item-note">{{line.note}}</small><div class="stepper"><button :aria-label="'Giảm '+line.name" @click="s.cart[i].quantity>1?s.cart[i].quantity--:s.cart.splice(i,1)">−</button><span>{{line.quantity}}</span><button :aria-label="'Tăng '+line.name" @click="s.cart[i].quantity=Math.min(99,s.cart[i].quantity+1)">+</button></div></div><div class="bill-line-end"><button class="icon-button" :aria-label="'Xóa '+line.name" @click="s.cart.splice(i,1)"><Icon name="close" :size="16"/></button><b>{{money(line.total)}}</b></div></article></div><footer class="bill-footer"><div class="total-row muted"><span>Tạm tính</span><b>{{money(s.total)}}</b></div><div class="total-row muted"><span>Giảm giá</span><span>0đ</span></div><div class="total-row grand-total"><strong>Tổng cộng</strong><strong>{{money(s.total)}}</strong></div><p class="bill-helper"><Icon name="shield" :size="14"/>Kiểm tra món và bàn trước khi lưu đơn</p><div class="bill-actions"><button class="btn outline" :disabled="!s.cart.length" @click="submit()"><Icon name="orders"/>Lưu đơn</button><button class="btn primary" :disabled="!s.cart.length||!s.canCollect" @click="submit(true)"><Icon name="wallet"/>Thanh toán</button></div></footer></aside><button class="mobile-cart-bar" @click="cartOpen=true"><span><Icon name="cart"/> {{count}} món</span><b>{{money(s.total)}}</b><span>Xem đơn <Icon name="next"/></span></button></div><ProductOptions v-if="selected" :product="selected" :initial="editIndex>=0?s.cart[editIndex]:undefined" @close="selected=undefined" @add="add"/><PaymentDialog v-if="payment" :order-id="payment.id" @close="payment=undefined"/></template>
